"""Hand evaluation for Texas Hold'em.

Determines the best 5-card hand from up to 7 cards and provides
comparable HandRank objects for determining winners.
"""

from enum import IntEnum
from itertools import combinations
from typing import List, Tuple

from .card import Card


class HandCategory(IntEnum):
    HIGH_CARD = 0
    ONE_PAIR = 1
    TWO_PAIR = 2
    THREE_OF_A_KIND = 3
    STRAIGHT = 4
    FLUSH = 5
    FULL_HOUSE = 6
    FOUR_OF_A_KIND = 7
    STRAIGHT_FLUSH = 8
    ROYAL_FLUSH = 9

    @property
    def name_cn(self) -> str:
        return {
            HandCategory.HIGH_CARD: "高牌",
            HandCategory.ONE_PAIR: "一对",
            HandCategory.TWO_PAIR: "两对",
            HandCategory.THREE_OF_A_KIND: "三条",
            HandCategory.STRAIGHT: "顺子",
            HandCategory.FLUSH: "同花",
            HandCategory.FULL_HOUSE: "葫芦",
            HandCategory.FOUR_OF_A_KIND: "四条",
            HandCategory.STRAIGHT_FLUSH: "同花顺",
            HandCategory.ROYAL_FLUSH: "皇家同花顺",
        }[self]


class HandRank:
    """Comparable hand ranking. Higher is better."""

    __slots__ = ("category", "tiebreakers")

    def __init__(self, category: HandCategory, tiebreakers: Tuple[int, ...]):
        self.category = category
        self.tiebreakers = tiebreakers

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, HandRank):
            return NotImplemented
        return self.category == other.category and self.tiebreakers == other.tiebreakers

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, HandRank):
            return NotImplemented
        if self.category != other.category:
            return self.category < other.category
        return self.tiebreakers < other.tiebreakers

    def __le__(self, other: object) -> bool:
        return self == other or self < other

    def __gt__(self, other: object) -> bool:
        if not isinstance(other, HandRank):
            return NotImplemented
        return other < self

    def __ge__(self, other: object) -> bool:
        return self == other or self > other

    def __repr__(self) -> str:
        return f"HandRank({self.category.name}, {self.tiebreakers})"

    @property
    def description(self) -> str:
        return self.category.name_cn


def _evaluate_5(cards: List[Card]) -> HandRank:
    """Evaluate exactly 5 cards and return a HandRank."""
    assert len(cards) == 5

    ranks = sorted([c.rank for c in cards], reverse=True)
    suits = [c.suit for c in cards]

    is_flush = len(set(suits)) == 1

    # Check for straight
    is_straight = False
    straight_high = 0
    if ranks[0] - ranks[4] == 4 and len(set(ranks)) == 5:
        is_straight = True
        straight_high = ranks[0]
    # Check wheel: A-2-3-4-5
    elif set(ranks) == {14, 2, 3, 4, 5}:
        is_straight = True
        straight_high = 5  # 5-high straight

    # Count rank frequencies
    from collections import Counter
    rank_counts = Counter(ranks)
    # Sort by (count desc, rank desc)
    count_rank_pairs = sorted(rank_counts.items(), key=lambda x: (x[1], x[0]), reverse=True)
    counts = [c for _, c in count_rank_pairs]
    sorted_ranks = tuple(r for r, _ in count_rank_pairs)

    if is_straight and is_flush:
        if straight_high == 14:
            return HandRank(HandCategory.ROYAL_FLUSH, (14,))
        return HandRank(HandCategory.STRAIGHT_FLUSH, (straight_high,))

    if counts[0] == 4:
        # Four of a kind: tiebreak by quad rank, then kicker
        return HandRank(HandCategory.FOUR_OF_A_KIND, sorted_ranks)

    if counts[0] == 3 and counts[1] == 2:
        # Full house: tiebreak by trips rank, then pair rank
        return HandRank(HandCategory.FULL_HOUSE, sorted_ranks)

    if is_flush:
        return HandRank(HandCategory.FLUSH, tuple(ranks))

    if is_straight:
        return HandRank(HandCategory.STRAIGHT, (straight_high,))

    if counts[0] == 3:
        # Three of a kind
        return HandRank(HandCategory.THREE_OF_A_KIND, sorted_ranks)

    if counts[0] == 2 and counts[1] == 2:
        # Two pair: sorted_ranks already has higher pair first
        return HandRank(HandCategory.TWO_PAIR, sorted_ranks)

    if counts[0] == 2:
        # One pair
        return HandRank(HandCategory.ONE_PAIR, sorted_ranks)

    return HandRank(HandCategory.HIGH_CARD, tuple(ranks))


def evaluate_hand(cards: List[Card]) -> HandRank:
    """Evaluate the best 5-card hand from a list of 5-7 cards."""
    if len(cards) < 5:
        raise ValueError(f"Need at least 5 cards, got {len(cards)}")
    if len(cards) == 5:
        return _evaluate_5(cards)

    best = None
    for combo in combinations(cards, 5):
        rank = _evaluate_5(list(combo))
        if best is None or rank > best:
            best = rank
    return best  # type: ignore


def hand_description(cards: List[Card]) -> str:
    """Return a human-readable description of the best hand."""
    rank = evaluate_hand(cards)
    return rank.description

