"""CLI interface for Limit Texas Hold'em."""

import os
import sys
from typing import List

from .card import Card
from .player import Player
from .game import LimitHoldemGame, Action, Stage, GameState
from .ai import AIPlayer


def clear_screen():
    os.system("cls" if os.name == "nt" else "clear")


def print_banner():
    print("=" * 56)
    print("         限注德州扑克 (Limit Texas Hold'em)")
    print("=" * 56)
    print()


def format_card(card: Card) -> str:
    return str(card)


def format_cards(cards: List[Card]) -> str:
    return " ".join(format_card(c) for c in cards)


def format_hidden_cards(n: int) -> str:
    return " ".join(["🂠"] * n)


def get_setup() -> dict:
    """Get game setup from user."""
    print_banner()

    # Number of AI opponents
    while True:
        try:
            n = int(input("请选择AI对手数量 (1-3): "))
            if 1 <= n <= 3:
                break
            print("请输入1到3之间的数字。")
        except ValueError:
            print("请输入有效数字。")

    # Difficulty
    print("\n难度级别:")
    print("  1 - 简单 (随机、被动)")
    print("  2 - 中等 (基本策略)")
    print("  3 - 困难 (高级策略、会诈唬)")
    while True:
        try:
            diff = int(input("\n请选择难度 (1-3): "))
            if 1 <= diff <= 3:
                break
            print("请输入1到3之间的数字。")
        except ValueError:
            print("请输入有效数字。")

    # Starting chips
    while True:
        try:
            chips_input = input("\n起始筹码 (默认1000): ").strip()
            if not chips_input:
                chips = 1000
            else:
                chips = int(chips_input)
                if chips < 100:
                    print("筹码至少为100。")
                    continue
            break
        except ValueError:
            print("请输入有效数字。")

    return {"num_ai": n, "difficulty": diff, "chips": chips}


def display_game_state(game: LimitHoldemGame, human_player: Player):
    """Display the current game state to the human player."""
    clear_screen()
    print_banner()

    # Stage info
    stage_names = {
        Stage.PREFLOP: "翻牌前",
        Stage.FLOP: "翻牌",
        Stage.TURN: "转牌",
        Stage.RIVER: "河牌",
        Stage.SHOWDOWN: "摊牌",
    }
    print(f"  阶段: {stage_names.get(game.stage, '?')}")
    print(f"  底池: {game.pot}")
    print(f"  庄家: {game.players[game.dealer_pos].name}")
    print()

    # Community cards
    if game.community_cards:
        print(f"  公共牌: {format_cards(game.community_cards)}")
    else:
        print("  公共牌: (无)")
    print()

    # All players info
    print("  ┌─────────────────────────────────────────────┐")
    for p in game.players:
        status = ""
        if p.is_folded:
            status = " [弃牌]"
        elif p.is_all_in:
            status = " [全下]"

        if p is human_player:
            cards_str = format_cards(p.hole_cards) if p.hole_cards else "??"
            marker = " ★"
        else:
            if p.is_folded:
                cards_str = "——"
            else:
                cards_str = format_hidden_cards(2) if p.hole_cards else "??"
            marker = ""

        bet_str = f"  下注: {p.bet_this_stage}" if p.bet_this_stage > 0 else ""
        print(f"  │ {p.name}{marker}: 筹码 {p.chips}{bet_str}{status}")

    print("  └─────────────────────────────────────────────┘")
    print()

    # Human player's cards (prominent display)
    if human_player.hole_cards:
        print(f"  你的手牌: {format_cards(human_player.hole_cards)}")
        print()


def human_action_handler(game_state: GameState) -> Action:
    """Get action from human player via CLI."""
    # Show available actions
    actions = []
    action_map = {}

    if game_state.can_check:
        actions.append("过牌(c)")
        action_map["c"] = Action.CHECK
    else:
        call_amount = game_state.to_call
        actions.append(f"跟注 {call_amount}(a)")
        action_map["a"] = Action.CALL

    if game_state.can_raise:
        actions.append("加注(r)")
        action_map["r"] = Action.RAISE

    if not game_state.can_check:
        actions.append("弃牌(f)")
        action_map["f"] = Action.FOLD

    print(f"  可用操作: {' | '.join(actions)}")

    while True:
        choice = input("  请选择操作: ").strip().lower()
        if choice in action_map:
            return action_map[choice]
        # Also accept full action names
        if choice in ("fold", "f", "弃牌"):
            if "f" in action_map:
                return Action.FOLD
        if choice in ("check", "c", "过牌"):
            if "c" in action_map:
                return Action.CHECK
        if choice in ("call", "a", "跟注"):
            if "a" in action_map:
                return Action.CALL
        if choice in ("raise", "r", "加注"):
            if "r" in action_map:
                return Action.RAISE
        print("  无效操作，请重新选择。")


def show_showdown(game: LimitHoldemGame):
    """Display showdown results."""
    print("\n  ══════════ 摊牌 ══════════")
    for p in game.players:
        if not p.is_folded and p.hole_cards:
            from .hand_eval import evaluate_hand
            if len(game.community_cards) >= 3:
                all_cards = p.hole_cards + game.community_cards
                hand_rank = evaluate_hand(all_cards)
                print(f"  {p.name}: {format_cards(p.hole_cards)} - {hand_rank.description}")
            else:
                print(f"  {p.name}: {format_cards(p.hole_cards)}")
    print()


def show_results(results: dict):
    """Display hand results."""
    print("  ──────────────────────────")
    for winner_info in results.get("winners", []):
        name = winner_info["player"]
        amount = winner_info["amount"]
        print(f"  🏆 {name} 赢得 {amount} 筹码!")
    print()


def run_game():
    """Main game loop."""
    setup = get_setup()
    clear_screen()

    # Create players
    human = Player("玩家", setup["chips"])
    players = [human]

    ai_names = ["AI_1", "AI_2", "AI_3"]
    ai_players = []
    for i in range(setup["num_ai"]):
        ai = AIPlayer(difficulty=setup["difficulty"])
        p = Player(ai_names[i], setup["chips"])
        players.append(p)
        ai_players.append((p, ai))

    # Create game
    game = LimitHoldemGame(players)

    # Set up action handlers
    def make_ai_handler(ai_instance: AIPlayer):
        def handler(gs: GameState) -> Action:
            action_str = ai_instance.decide(gs)
            return Action[action_str.upper()]
        return handler

    game.action_handlers["玩家"] = human_action_handler
    for p, ai in ai_players:
