def clear_screen():
    os.system("cls" if os.name == "nt" else "clear")


def print_banner():
    print("=" * 56)
    print("         限注德州扑克 (Limit Texas Hold'em)")
    print("=" * 56)
    print()


def format_card(card: Card) -> str:
    return str(card)


def format_cards(cards: List[Card]) -> str:
    return " ".join(format_card(c) for c in cards)


def format_hidden_cards(n: int) -> str:
    return " ".join(["🂠"] * n)


def get_setup() -> dict:
    """Get game setup from user."""
    print_banner()

    # Number of AI opponents
    while True:
        try:
            n = int(input("请选择AI对手数量 (1-3): "))
            if 1 <= n <= 3:
                break
            print("请输入1到3之间的数字。")
        except ValueError:
            print("请输入有效数字。")

    # Difficulty
    print("\n难度级别:")
    print("  1 - 简单 (随机、被动)")
    print("  2 - 中等 (基本策略)")
    print("  3 - 困难 (高级策略、会诈唬)")
    while True:
        try:
            diff = int(input("\n请选择难度 (1-3): "))
            if 1 <= diff <= 3:
                break
            print("请输入1到3之间的数字。")
        except ValueError:
            print("请输入有效数字。")

    # Starting chips
    while True:
        try:
            chips_input = input("\n起始筹码 (默认1000): ").strip()
            if not chips_input:
                chips = 1000
            else:
                chips = int(chips_input)
                if chips < 100:
                    print("筹码至少为100。")
                    continue
            break
        except ValueError:
            print("请输入有效数字。")

    return {"num_ai": n, "difficulty": diff, "chips": chips}


