    """Display the current game state to the human player."""
    clear_screen()
    print_banner()

    # Stage info
    stage_names = {
        Stage.PREFLOP: "翻牌前",
        Stage.FLOP: "翻牌",
        Stage.TURN: "转牌",
        Stage.RIVER: "河牌",
        Stage.SHOWDOWN: "摊牌",
    }
    print(f"  阶段: {stage_names.get(game.stage, '?')}")
    print(f"  底池: {game.pot}")
    print(f"  庄家: {game.players[game.dealer_pos].name}")
    print()

    # Community cards
    if game.community_cards:
        print(f"  公共牌: {format_cards(game.community_cards)}")
    else:
        print("  公共牌: (无)")
    print()

    # All players info
    print("  ┌─────────────────────────────────────────────┐")
    for p in game.players:
